// Moved from the pack's startup_scripts/items/cans.js 2026-10-25, rows unchanged.
// Creative Delight startup script, loaded from the jar after the pack's startup_scripts, so the dicts exist here.
// Restart to apply.
//
// Food cans made in kubejs/data/creative_delight/kubejs/creativeengineering/canning.js (ingredient + empty can, or fewer ingredients + an additive).
// Every can is generated by tools/gen_can_types.py into generation_scripts/food/can_types.json and registered below:
// one meal = a fixed meal (raw veggie Baked Potato 5/6, raw fruit Fruit Meal 5/3, raw meat Meat Meal 5/3, raw fish
// Fish Meal 4/2) or the food it holds x the section multiplier, effects copied with scaled durations. Sections, goals
// and the rows live in SECTIONS / EXPLICIT in the script (mirroring the Goal comments in canning.js).
// Cans with their own sprite use kubejs/assets/creativeengineering/textures/item/<id>.png (drawn in
// textureswapper/canned/newcan, "texture": null); the rest borrow their family's (GROUP_SPRITE: carrot, apple, raw
// beef, raw salmon, or the Canned Goods can of the same family). Some Canned Goods sprites are replaced under
// kubejs/assets/canned_goods/.
//
// Food values are one serving (one meal). The number of servings per can lives in
// generation_scripts/food/can_servings.json (patcherMod food.CanServings), not here.
// KubeJS saturation() is the modifier: saturation points = hunger x modifier x 2.
// Dict keys: startup_scripts/_lib/item_dict.js generated cans block. Food types: generation_scripts/food/food_types.json.
// Not canned: mint, acorn, grapes, mite crust, Alex's Mobs bananas, and raw or cooked ham, chevon, hoglin, kangaroo,
// moose, bison, bunfungus. Coverage: feature_writeup/can_parity.md.
// Cans marked "existing" are Canned Goods items (canned_bread, canned_beef...): only their food values change, including
// the Canned Goods cans no recipe makes (their own saturation modifiers are saturation points, up to 42).

// Generated cans (tools/gen_can_types.py -> generation_scripts/food/can_types.json)
function ceCanTypes() {
    var path = 'kubejs/generation_scripts/food/can_types.json'
    try { return JSON.parse(String(JsonIO.readString(path))).cans } catch (err) {
        console.error('[cans] could not read ' + path + ': ' + err)
        return {}
    }
}

function ceCanFood(f, c) {
    // flags set both ways: a Canned Goods can's builder starts from its own properties (cookies and golden apple cans are meat)
    f.hunger(c.hunger).saturation(c.modifier).meat(!!c.meat).fastToEat(!!c.fast).alwaysEdible(!!c.always)
    c.effects.forEach(fx => f.effect(fx.effect, fx.ticks, fx.amp, fx.chance))
    if (c.clear_effects) f.eaten(ev => ev.entity.removeAllEffects())   // Canned Powdered Milk
}

StartupEvents.registry('item', e => {
    var i = global.item
    var cans = ceCanTypes()
    var made = 0
    Object.keys(cans).forEach(key => {
        var c = cans[key]
        if (c.existing) return
        var id = i[key]
        if (typeof id !== 'string') { console.warn('[cans] ' + key + ' has no item_dict key, run tools/gen_can_types.py'); return }
        try {
            var b = e.create(id).displayName(c.name)
            if (c.food !== false) b.food(f => ceCanFood(f, c))   // false: an ingredient can (Canned Dough)
            if (c.texture) b.texture(c.texture)   // null: own sprite at creativeengineering:item/<id>
            if (c.glow) b.glow(true)
            made++
        } catch (err) {
            console.warn('[cans] could not register ' + id + ': ' + err)
        }
    })
    console.log('[cans] registered ' + made + ' generated cans')
})

// Canned Goods cans: the same food values as the generated cans (their own modifiers are 1 to 42).
ItemEvents.modification(e => {
    var i = global.item
    var cans = ceCanTypes()
    Object.keys(cans).forEach(key => {
        var c = cans[key]
        if (!c.existing) return
        var id = i[key]
        if (typeof id !== 'string') { console.warn('[cans] ' + key + ' has no item_dict key'); return }
        try {
            e.modify(id, item => item.setFoodProperties(f => ceCanFood(f, c)))
        } catch (err) {
            console.warn('[cans] could not set food on ' + id + ': ' + err)
        }
    })
})
